#!/usr/bin/env python3
"""Extract declarations, their docstrings and § citations from Lean files.

Usage: extract.py OUT.json ROOT FILE... ; writes declarations (with statement text) to OUT.json.
"""
import os, re, sys, json

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = sys.argv[1]
ROOT = sys.argv[2]
FILES = sys.argv[3:]

DECL = re.compile(r'^\s*(?:@\[[^\]]*\]\s*)?(?:(?:private|protected|noncomputable|partial|unsafe|nonrec)\s+)*'
                  r'(def|theorem|lemma|structure|inductive|abbrev|instance|class|opaque|axiom|example)\b\s*([^\s:({\[]*)')
FIELD = re.compile(r'^\s{2,}([A-Za-z_][A-Za-z0-9_\'.]*)\s*(?:\{[^}]*\}\s*)?(?:\([^)]*\)\s*)*:')
CTOR = re.compile(r'^\s*\|\s*([A-Za-z_][A-Za-z0-9_\'.]*)')
NS = re.compile(r'^\s*namespace\s+(\S+)')
SEC = re.compile(r'^\s*section(?:\s+(\S+))?\s*$')
END = re.compile(r'^\s*end(?:\s+(\S+))?\s*$')

DASH = '[–-]'
def cites(doc):
    """Return set of (sec, item) with item None (whole), int, or '¶p'."""
    out = set()
    # ranges of items §N.k–§M.m or §N.k–m
    for m in re.finditer(r'§(\d+)\.(\d+)[a-z]?\s*' + DASH + r'\s*§?(\d+)(?:\.(\d+))?', doc):
        a, i, b, j = m.group(1), m.group(2), m.group(3), m.group(4)
        if j is None:  # §N.k–m
            for k in range(int(i), int(b) + 1): out.add((int(a), k))
        elif a == b:
            for k in range(int(i), int(j) + 1): out.add((int(a), k))
        else:
            out.add((int(a), int(i))); out.add((int(b), int(j)))
    # whole-section ranges §N–§M
    for m in re.finditer(r'§(\d+)\s*' + DASH + r'\s*§(\d+)(?!\d)(?!\.\d)', doc):
        for k in range(int(m.group(1)), int(m.group(2)) + 1): out.add((k, None))
    # §N, item(s) k(–m)
    for m in re.finditer(r'§(\d+)(?:\s*,\s*|\s*\(\s*)items?\s+(\d+)(?:\s*' + DASH + r'\s*(\d+))?', doc):
        a, i, j = int(m.group(1)), int(m.group(2)), m.group(3)
        for k in range(i, (int(j) if j else i) + 1): out.add((a, k))
    # §N.k
    for m in re.finditer(r'§(\d+)\.(\d+)', doc):
        out.add((int(m.group(1)), int(m.group(2))))
    # §N ¶p(–¶q)
    for m in re.finditer(r'§(\d+)\s+¶(\d+)(?:\s*' + DASH + r'\s*¶?(\d+))?', doc):
        a, i, j = int(m.group(1)), int(m.group(2)), m.group(3)
        for k in range(i, (int(j) if j else i) + 1): out.add((a, '¶%d' % k))
    # bare §N
    for m in re.finditer(r'§(\d+)(?!\d)(?!\.\d)', doc):
        out.add((int(m.group(1)), None))
    return out

rows = []
for f in FILES:
    rel = os.path.relpath(f, ROOT)
    lines = open(f, encoding='utf-8').read().split('\n')
    stack = []  # (kind, name)
    doc = None
    in_doc = False
    in_comment = False
    buf = []
    cur_struct = None  # name of structure/inductive being defined (for fields/ctors)
    i = 0
    for ln, line in enumerate(lines, 1):
        s = line
        if in_comment:
            if '-/' in s: in_comment = False
            continue
        if in_doc:
            buf.append(s)
            if '-/' in s:
                in_doc = False
                doc = '\n'.join(buf)
                buf = []
            continue
        st = s.strip()
        if st.startswith('/--'):
            buf = [s]
            if '-/' in st[3:]:
                doc = s
                buf = []
            else:
                in_doc = True
            # docstring on same line as field: "/-- ... -/ field : T" rare
            continue
        if st.startswith('/-'):
            if '-/' not in st[2:]:
                in_comment = True
            doc = None
            continue
        m = NS.match(s)
        if m:
            stack.append(('ns', m.group(1))); doc = None; cur_struct = None; continue
        m = SEC.match(s)
        if m:
            stack.append(('sec', m.group(1) or '')); doc = None; cur_struct = None; continue
        m = END.match(s)
        if m and st.startswith('end'):
            if stack: stack.pop()
            doc = None; cur_struct = None; continue
        ns = '.'.join(n for k, n in stack if k == 'ns')
        m = DECL.match(s)
        if m and not s.startswith(' ' * 4):
            kind, name = m.group(1), m.group(2)
            if kind == 'instance' and (not name or name.startswith(':')):
                name = '(instance@%d)' % ln
            full = (ns + '.' if ns else '') + name
            sig = []
            for t in lines[ln - 1:ln + 39]:
                if sig and (t.strip() == '' or DECL.match(t)): break
                cut = min([k for k in (t.find(':='), t.find(' where')) if k >= 0], default=-1)
                if cut >= 0: sig.append(t[:cut]); break
                sig.append(t)
            rows.append(dict(file=rel, line=ln, kind=kind, name=full, doc=doc or '',
                             sig=' '.join(' '.join(sig).split()),
                             cites=sorted(cites(doc or ''), key=str)))
            cur_struct = full if kind in ('structure', 'inductive', 'class') else None
            doc = None
            continue
        if cur_struct and doc is not None:
            m = CTOR.match(s) or FIELD.match(s)
            if m:
                full = cur_struct + '.' + m.group(1)
                rows.append(dict(file=rel, line=ln, kind='field', name=full, doc=doc,
                                 cites=sorted(cites(doc), key=str)))
                doc = None
                continue
        if st and not st.startswith('--') and not st.startswith('@['):
            # any other code line: a pending docstring would be for something unmatched
            if doc is not None and (DECL.match(s) is None):
                pass
        if st == '' and cur_struct is None:
            pass

json.dump(rows, open(OUT, 'w'), ensure_ascii=False, indent=0)
print(len(rows), 'declarations')
"""Citation index: clause key -> declarations whose docstring cites it (current tree).
Usage: index.py DECLS.json OUT.json. Keys: 'N' (bare §N), 'N.k' (item), 'N ¶p' (paragraph), 'N~' (inside a §N–§M range)."""
import json, re, sys, collections
D = '[–-]'
def cites(doc):
    out = set()
    doc = re.sub(r'material\s+§\d+[a-z]?', ' ', doc)  # sections of the attached corpus material, not of the spec
    for m in re.finditer(r'§(\d+)\s*' + D + r'\s*§(\d+)(?!\d)(?!\.\d)', doc):
        for k in range(int(m.group(1)), int(m.group(2)) + 1): out.add('%d~' % k)
    doc = re.sub(r'§(\d+)\s*' + D + r'\s*§(\d+)(?!\d)(?!\.\d)', ' ', doc)
    for m in re.finditer(r'§(\d+)\.(\d+)[a-z]?\s*' + D + r'\s*§?(\d+)(?:\.(\d+))?', doc):
        a, i, b, j = m.groups()
        if j is None: out.update('%s.%d' % (a, k) for k in range(int(i), int(b) + 1))
        elif a == b: out.update('%s.%d' % (a, k) for k in range(int(i), int(j) + 1))
        else: out.update(('%s.%s' % (a, i), '%s.%s' % (b, j)))
    for m in re.finditer(r'§(\d+)(?:\s*,\s*|\s*\(\s*)(?:items?|cases?)\s+(\d+)(?:\s*' + D + r'\s*(\d+))?', doc):
        a, i, j = int(m.group(1)), int(m.group(2)), m.group(3)
        out.update('%d.%d' % (a, k) for k in range(i, (int(j) if j else i) + 1))
    for m in re.finditer(r'§(\d+)\.(\d+)', doc): out.add('%s.%s' % m.groups())
    for m in re.finditer(r'§(\d+)\s+¶(\d+)(?:\s*' + D + r'\s*¶?(\d+))?', doc):
        a, i, j = int(m.group(1)), int(m.group(2)), m.group(3)
        out.update('%d ¶%d' % (a, k) for k in range(i, (int(j) if j else i) + 1))
    for m in re.finditer(r'§(\d+)(?!\d)(?!\.\d)', doc): out.add(m.group(1))
    return out
idx = collections.defaultdict(list)
nocite = []
for r in json.load(open(sys.argv[1])):
    if r['kind'] == 'example': continue
    c = cites(r['doc'])
    mod = r['file'][len('Ern/'):-len('.lean')].replace('/', '.')
    short = r['name'].replace('Ern.MemoryModel.', '').replace('Ern.Lib.', 'Lib.').replace('Ern.Corpus.', 'Corpus.')
    if not c and r['kind'] != 'instance': nocite.append((mod, short, r['kind'], r['line']))
    for k in c: idx[k].append(dict(mod=mod, name=short, kind=r['kind'], file=r['file'], line=r['line']))
json.dump(dict(index=idx, nocite=nocite), open(sys.argv[2], 'w'), ensure_ascii=False)
print(len(idx), 'keys;', len(nocite), 'declarations without a § citation')
"""Diff declarations between two extractions: added, removed, statement changed, docstring changed.
Usage: diffdecls.py OLD.json NEW.json"""
import json, sys, collections
def load(p):
    d = {}
    for r in json.load(open(p)):
        if r['kind'] in ('example',) or r['name'].endswith(')'):  # instances by line number are unstable
            continue
        d[(r['name'], r['kind'])] = r
    return d
a, b = load(sys.argv[1]), load(sys.argv[2])
for tag, keys in (('ADDED', sorted(set(b) - set(a))), ('REMOVED', sorted(set(a) - set(b)))):
    for k in keys:
        r = (b if tag == 'ADDED' else a)[k]
        print(tag, r['file'], r['line'], r['kind'], r['name'], sep='\t')
for k in sorted(set(a) & set(b)):
    if a[k].get('sig') != b[k].get('sig'):
        print('STMT', b[k]['file'], b[k]['line'], k[1], k[0], sep='\t')
    elif a[k]['doc'] != b[k]['doc']:
        print('DOC', b[k]['file'], b[k]['line'], k[1], k[0], sep='\t')
